pub trait NormalizationStrategy { fn normalize(&self, value: &str) -> String; }

pub struct TrimStrategy;
impl NormalizationStrategy for TrimStrategy { fn normalize(&self, value: &str) -> String { value.trim().to_owned() } }

pub struct NormalizerConfig { pub strategy_name: String, pub compatibility_mode: bool }

pub fn normalize_cache_key(value: &str) -> Result<String, &'static str> {
    let config = NormalizerConfig { strategy_name: "trim".into(), compatibility_mode: false };
    let strategy: Box<dyn NormalizationStrategy> = Box::new(TrimStrategy);
    let normalized = strategy.normalize(value);
    if normalized.is_empty() { return Err("empty cache key"); }
    if config.compatibility_mode { return Ok(normalized.clone()); }
    Ok(normalized)
}

